-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/abyssea/Grauberg_Dominion_Op_11.lua"]={["Path"]="scripts/quests/abyssea/Grauberg_Dominion_Op_11.lua",["SHA256"]="534713e02482cf01bd2652e64338e5e9c1e23ba4f6825be0eb81247a91bd9743",["Text"]="-----------------------------------\n-- Grauberg - Dominion Op #11\n-----------------------------------\n-- !addquest 8 188\n-- Dominion Sergeant (Tosuka-Porika's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_11_GRAUBERG)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_GRAUBERG] =\n        {\n            ['Seelie'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 598)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Grauberg_Dominion_Op_12.lua"]={["Path"]="scripts/quests/abyssea/Grauberg_Dominion_Op_12.lua",["SHA256"]="50666184591b5ae3337d4e888def4c5ab5bb2b7d06631b314808fe43cf9adea9",["Text"]="-----------------------------------\n-- Grauberg - Dominion Op #12\n-----------------------------------\n-- !addquest 8 189\n-- Dominion Sergeant (Tosuka-Porika's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_12_GRAUBERG)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_GRAUBERG] =\n        {\n            ['Unseelie'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 599)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Grauberg_Dominion_Op_13.lua"]={["Path"]="scripts/quests/abyssea/Grauberg_Dominion_Op_13.lua",["SHA256"]="bdb0c575a5819eb152ba08db28096efef9820325ed26c998a4875ab20118552a",["Text"]="-----------------------------------\n-- Grauberg - Dominion Op #13\n-----------------------------------\n-- !addquest 8 190\n-- Dominion Sergeant (Cornelia's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_13_GRAUBERG)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_GRAUBERG] =\n        {\n            ['Goblin_Plunderer'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 600)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Grauberg_Dominion_Op_14.lua"]={["Path"]="scripts/quests/abyssea/Grauberg_Dominion_Op_14.lua",["SHA256"]="e261f27d601614579cf75223023a233073ae78d2b619ff318ff117767822ab03",["Text"]="-----------------------------------\n-- Grauberg - Dominion Op #14\n-----------------------------------\n-- !addquest 8 191\n-- Dominion Sergeant (Cornelia's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_14_GRAUBERG)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_GRAUBERG] =\n        {\n            ['Goblin_Meatgrinder'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 601)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Heart_of_Madness.lua"]={["Path"]="scripts/quests/abyssea/Heart_of_Madness.lua",["SHA256"]="7736435f0d5b884d6c52434af906a5dbf060028b09a3e97387ef13dfa956f655",["Text"]="-----------------------------------\n-- Heart of Madness\n-----------------------------------\n-- !addquest 8 169\n-- Joachim : !pos -52.844 0 -9.978 246\n-- Flagged on completion of An Officer and a Pirate.\n-- Complete when any 5 of the 9 zone quests are completed and player talks to Joachim. Flags Tenuous Existence upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.HEART_OF_MADNESS)\n\nquest.reward = {}\n\nlocal zoneQuests =\n{\n    xi.quest.id.abyssea.A_GOLDSTRUCK_GIGAS,\n    xi.quest.id.abyssea.TO_PASTE_A_PEISTE,\n    xi.quest.id.abyssea.MEGADRILE_MENACE,\n    xi.quest.id.abyssea.THE_BEAST_OF_BASTORE,\n    xi.quest.id.abyssea.A_DELECTABLE_DEMON,\n    xi.quest.id.abyssea.A_FLUTTERY_FIEND,\n    xi.quest.id.abyssea.A_BEAKED_BLUSTERER,\n    xi.quest.id.abyssea.A_MAN_EATING_MITE,\n    xi.quest.id.abyssea.AN_ULCEROUS_URAGNITE,\n}\n\nlocal function countCompletedZoneQuests(player)\n    local count = 0\n    for _, questId in ipairs(zoneQuests) do\n        if player:hasCompletedQuest(xi.questLog.ABYSSEA, questId) then\n            count = count + 1\n        end\n    end\n\n    return count\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and countCompletedZoneQuests(player) >= 5\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(335)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [335] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.TENUOUS_EXISTENCE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Heroes_of_Abyssea.lua"]={["Path"]="scripts/quests/abyssea/Heroes_of_Abyssea.lua",["SHA256"]="e0eee8aea80238808005eed884b4bccafae65e4b25612ce55446c30230cff66d",["Text"]="-----------------------------------\n-- Heroes of Abyssea\n-----------------------------------\n-- !addquest 8 179\n-- Joachim : !pos -52.844 0 -9.978 246\n-- Flag when any of An Ulcerous Uragnite, A Beaked Blusterer, A Man-eating Mite started.\n-- Complete when all three are completed and player talks to Joachim again.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.HEROES_OF_ABYSSEA)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                (\n                    player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.AN_ULCEROUS_URAGNITE) > xi.questStatus.QUEST_AVAILABLE or\n                    player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_BEAKED_BLUSTERER) > xi.questStatus.QUEST_AVAILABLE or\n                    player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_MAN_EATING_MITE) > xi.questStatus.QUEST_AVAILABLE\n                )\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(340)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [340] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasCompletedQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.AN_ULCEROUS_URAGNITE) and\n                player:hasCompletedQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_BEAKED_BLUSTERER) and\n                player:hasCompletedQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_MAN_EATING_MITE)\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(341)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [341] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Lost_Memories.lua"]={["Path"]="scripts/quests/abyssea/Lost_Memories.lua",["SHA256"]="5051674c1c9c61baa071dd6f0206d5a8b48b7b27b9d44d6d37ba6f07908bd14e",["Text"]="-----------------------------------\n-- Lost Memories\n-----------------------------------\n-- !addquest 8 9\n-- Halver : !pos: 600 40 -515 132\n-----------------------------------\nlocal ID = zones[xi.zone.ABYSSEA_LA_THEINE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.LOST_MEMORIES)\n\nquest.reward = {\n    keyItem     = xi.keyItem.VIAL_OF_LAMBENT_POTION,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getFameLevel(xi.fameArea.ABYSSEA_LATHEINE) < 5\n        end,\n\n        [xi.zone.ABYSSEA_LA_THEINE] =\n        {\n            ['Halver'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(162)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getFameLevel(xi.fameArea.ABYSSEA_LATHEINE) >= 5\n        end,\n\n        [xi.zone.ABYSSEA_LA_THEINE] =\n        {\n            ['Halver'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(165)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [165] = function(player, csid, option, npc)\n                    if option ~= 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_LA_THEINE] =\n        {\n            ['Halver'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(163)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.LAMBENT_SCALE, 2 } }) then\n                        return quest:event(164)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [164] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    --TODO add repeat quest functionality?\n                    player:addCurrency('cruor', 480)\n                    player:messageSpecial(ID.text.CRUOR_TOTAL, 480, player:getCurrency('cruor'))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Meanwhile_Back_on_Abyssea.lua"]={["Path"]="scripts/quests/abyssea/Meanwhile_Back_on_Abyssea.lua",["SHA256"]="4606fcf550d9f610bd7f2b80e9f98adbcbea001902a03bb3bb263d957ab20894",["Text"]="-----------------------------------\n-- Meanwhile, Back on Abyssea\n-----------------------------------\n-- !addquest 8 185\n-- Joachim  : !pos -52.844 0 -9.978 246\n-- Prishe   : !pos 536.353 -499.999 -591.338 255\n-- Flagged on completion of The Wyrm God.\n-- Talk to Joachim. Zone into the Hall of the Gods between 18:00 and 5:00. Talk to Prishe to flag A Moonlight Requite.\n-- A Moonlight Requite signifies that you have completed the main Abyssea story, it cannot be completed.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.MEANWHILE_BACK_ON_ABYSSEA)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.ABYSSITE_OF_THE_COSMOS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(345)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [345] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                quest:getVar(player, 'Prog') == 1\n        end,\n\n        [xi.zone.HALL_OF_THE_GODS] =\n        {\n            onZoneIn = function(player, prevZone)\n                local hour = VanadielHour()\n                if hour >= 18 or hour < 5 then\n                    return 9\n                end\n            end,\n\n            onEventFinish =\n            {\n                [9] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                quest:getVar(player, 'Prog') == 2\n        end,\n\n        [xi.zone.ABYSSEA_EMPYREAL_PARADOX] =\n        {\n            ['Prishe'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(204)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [204] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_MOONLIGHT_REQUITE)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.ABYSSEA_EMPYREAL_PARADOX] =\n        {\n            ['Prishe'] = quest:event(207):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Megadrile_Menace.lua"]={["Path"]="scripts/quests/abyssea/Megadrile_Menace.lua",["SHA256"]="964175455344cb6308b3fe567eb8b704fe82fb6abd51b6397c9b9fec60130aa9",["Text"]="-----------------------------------\n-- Megadrile Menace\n-----------------------------------\n-- !addquest 8 165\n-- Cavernous Maw    : !pos -28.000 46.000 -685.000 117\n-- Glavoid          : !spawnmob 16961930\n-----------------------------------\nlocal ID = zones[xi.zone.TAHRONGI_CANYON]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.MEGADRILE_MENACE)\n\nquest.reward = { }\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.abyssea.getHeldTraverserStones(player) >= 1 and\n                player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAHRONGI_CANYON] =\n        {\n            ['Cavernous_Maw'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(38)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [38] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    player:addCurrency('cruor', 50)\n                    player:messageSpecial(ID.text.CRUOR_TOTAL, 50, player:getCurrency('cruor'))\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasTitle(xi.title.GLAVOID_STAMPEDER)\n        end,\n\n        [xi.zone.TAHRONGI_CANYON] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 39\n            end,\n\n            onEventUpdate =\n            {\n                [39] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(xi.abyssea.getZoneKIReward(player))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [39] = function(player, csid, option, npc)\n                    -- NOTE: Give the key item prior to completing the quest so that we reward the correct\n                    -- KI!  If we complete first, it'll adjust the total completed count, and be off by one!\n                    npcUtil.giveKeyItem(player, xi.abyssea.getZoneKIReward(player))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Scars_of_Abyssea.lua"]={["Path"]="scripts/quests/abyssea/Scars_of_Abyssea.lua",["SHA256"]="35a1468f60bfaa16abece8e21220d9521a470009f2ef526ffa0d3837e478303c",["Text"]="-----------------------------------\n-- Scars of Abyssea\n-----------------------------------\n-- !addquest 8 175\n-- Joachim : !pos -52.844 0 -9.978 246\n-- Flag when any of A Fluttery Fiend, The Beast of Bastore, A Delectable Demon started.\n-- Complete when all three are completed and player talks to Joachim again.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.SCARS_OF_ABYSSEA)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                (\n                    player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.THE_BEAST_OF_BASTORE) > xi.questStatus.QUEST_AVAILABLE or\n                    player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_DELECTABLE_DEMON) > xi.questStatus.QUEST_AVAILABLE or\n                    player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_FLUTTERY_FIEND) > xi.questStatus.QUEST_AVAILABLE\n                )\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(337)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [337] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasCompletedQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.THE_BEAST_OF_BASTORE) and\n                player:hasCompletedQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_DELECTABLE_DEMON) and\n                player:hasCompletedQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_FLUTTERY_FIEND)\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(338)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [338] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Tenuous_Existence.lua"]={["Path"]="scripts/quests/abyssea/Tenuous_Existence.lua",["SHA256"]="99b1287390156d41e56bbbf634f057f071acbba5b2a14573661e66f30504335d",["Text"]="-----------------------------------\n-- Tenuous Existence\n-----------------------------------\n-- !addquest 8 170\n-- qm3     : !pos -179 8 254 102\n-- Joachim : !pos -52.844 0 -9.978 246\n-- Flagged on completion of Heart of Madness.\n-- Click ??? in La Theine Plateau between 18:00 and 5:00, then return to Joachim. Flags Champions of Abyssea upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.TENUOUS_EXISTENCE)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                VanadielHour() >= 18 and\n                VanadielHour() < 5\n        end,\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['qm3'] = quest:progressEvent(12),\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and quest:getVar(player, 'Prog') == 1\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(336)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [336] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.CHAMPIONS_OF_ABYSSEA)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/The_Beast_of_Bastore.lua"]={["Path"]="scripts/quests/abyssea/The_Beast_of_Bastore.lua",["SHA256"]="3c4ea1828335b168c1946af897c0c384c1fd28aba6dee74e04dcacfdf37dd284",["Text"]="-----------------------------------\n-- The Beast of Bastore\n-----------------------------------\n-- !addquest 8 172\n-- Cavernous Maw    : !pos 246.318 -0.709 5.706 104\n-- Sedna            : !spawnmob 17666500\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.THE_BEAST_OF_BASTORE)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.abyssea.getHeldTraverserStones(player) >= 1 and\n                player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.JUGNER_FOREST] =\n        {\n            ['Cavernous_Maw_2'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(48)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [48] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasTitle(xi.title.SEDNA_TUSKBREAKER)\n        end,\n\n        [xi.zone.JUGNER_FOREST] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 49\n            end,\n\n            onEventUpdate =\n            {\n                [49] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(xi.abyssea.getZoneKIReward(player))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [49] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.abyssea.getZoneKIReward(player))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/The_Forbidden_Frontier.lua"]={["Path"]="scripts/quests/abyssea/The_Forbidden_Frontier.lua",["SHA256"]="e94f7a201f9f5eabccc35255059bb4bd54290e44fdd3ec55a9a07411cb674993",["Text"]="-----------------------------------\n-- The Forbidden Frontier\n-----------------------------------\n-- !addquest 8 166\n-- Joachim : !pos -52.844 0 -9.978 246\n-- Flag when any of A Goldstruck Gigas, To Paste a Peiste, Megadrile Menace started.\n-- Complete when all three are completed and player talks to Joachim again.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.THE_FORBIDDEN_FRONTIER)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                (\n                    player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_GOLDSTRUCK_GIGAS) > xi.questStatus.QUEST_AVAILABLE or\n                    player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.TO_PASTE_A_PEISTE) > xi.questStatus.QUEST_AVAILABLE or\n                    player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.MEGADRILE_MENACE) > xi.questStatus.QUEST_AVAILABLE\n                )\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(331)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [331] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasCompletedQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_GOLDSTRUCK_GIGAS) and\n                player:hasCompletedQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.TO_PASTE_A_PEISTE) and\n                player:hasCompletedQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.MEGADRILE_MENACE)\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(332)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [332] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/The_Truth_Beckons.lua"]={["Path"]="scripts/quests/abyssea/The_Truth_Beckons.lua",["SHA256"]="69627ef725e2f06c57250cb3db30bffb6a1130f9bade335b41d025c5758d798b",["Text"]="-----------------------------------\n-- The Truth Beckons\n-----------------------------------\n-- !addquest 8 161\n-- Joachim : !pos -52.844 0 -9.978 246\n-- Flagged on completion of A Journey Begins. Flags Dawn of Death upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.THE_TRUTH_BECKONS)\n\nquest.reward = {}\n\nlocal handleOnZoneIn = function(player, prevZone)\n    quest:setVar(player, 'Prog', 1)\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(327, 0, 0, xi.abyssea.getTraverserCap(player))\n                    else\n                        return quest:progressEvent(326)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [327] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.ABYSSEA_KONSCHTAT] =\n        {\n            onZoneIn = handleOnZoneIn,\n        },\n\n        [xi.zone.ABYSSEA_LA_THEINE] =\n        {\n            onZoneIn = handleOnZoneIn,\n        },\n\n        [xi.zone.ABYSSEA_TAHRONGI] =\n        {\n            onZoneIn = handleOnZoneIn,\n        },\n\n        [xi.zone.ABYSSEA_ATTOHWA] =\n        {\n            onZoneIn = handleOnZoneIn,\n        },\n\n        [xi.zone.ABYSSEA_MISAREAUX] =\n        {\n            onZoneIn = handleOnZoneIn,\n        },\n\n        [xi.zone.ABYSSEA_VUNKERL] =\n        {\n            onZoneIn = handleOnZoneIn,\n        },\n\n        [xi.zone.ABYSSEA_ALTEPA] =\n        {\n            onZoneIn = handleOnZoneIn,\n        },\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            onZoneIn = handleOnZoneIn,\n        },\n\n        [xi.zone.ABYSSEA_GRAUBERG]  =\n        {\n            onZoneIn = handleOnZoneIn,\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/The_Wyrm_God.lua"]={["Path"]="scripts/quests/abyssea/The_Wyrm_God.lua",["SHA256"]="00fcb75b76b7f0b3195be920c65c3ff3d5aa840c6db1ff84a9e2e171227d30e7",["Text"]="-----------------------------------\n-- The Wyrm God\n-----------------------------------\n-- !addquest 8 184\n-- TR_Entrance    : !pos 539.861 -500.000 -594.576 255\n-- Prishe         : !pos 536.353 -499.999 -591.338 255\n-- Flagged on completion of Beneath a Blood Red Sky.\n-- Defeat Shinryu in the Abyssea-Empyreal Paradox within The Wyrm God battlefield. Talk to Prishe for a CS. Flags \"Meanwhile, back on Abyssea\" upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.THE_WYRM_GOD)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_EMPYREAL_PARADOX] =\n        {\n            ['TR_Entrance'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(208)\n                    end\n                end,\n            },\n\n            ['Prishe'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(203)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [208] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [32001] = function(player, csid, option, npc)\n                    -- TODO: 'battlefieldWin' local var should be set on successful completion of\n                    -- the BCNM with its BCNM ID.  See other examples of this pattern implemented\n                    -- in various missions.\n\n                    if\n                        player:getLocalVar('battlefieldWin') == xi.battlefield.id.THE_WYRM_GOD and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n\n                [203] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.MEANWHILE_BACK_ON_ABYSSEA)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.ABYSSEA_EMPYREAL_PARADOX] =\n        {\n            ['Prishe'] = quest:event(206):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/To_Paste_a_Peiste.lua"]={["Path"]="scripts/quests/abyssea/To_Paste_a_Peiste.lua",["SHA256"]="b7b9cac3d3402df8f6a9936024a6e4b6219da0f308f130adf7bf71a24282c893",["Text"]="-----------------------------------\n-- To Paste a Peiste\n-----------------------------------\n-- !addquest 8 164\n-- Cavernous Maw    : !pos 95.344 -69.080 -580.008 108\n-- Kukulkan         : !spawnmob 16838872\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.TO_PASTE_A_PEISTE)\n\nquest.reward = { }\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.abyssea.getHeldTraverserStones(player) >= 1 and\n                player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KONSCHTAT_HIGHLANDS] =\n        {\n            ['Cavernous_Maw'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(0)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasTitle(xi.title.KUKULKAN_DEFANGER)\n        end,\n\n        [xi.zone.KONSCHTAT_HIGHLANDS] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 1\n            end,\n\n            onEventUpdate =\n            {\n                [1] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(xi.abyssea.getZoneKIReward(player))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    -- NOTE: Give the key item prior to completing the quest so that we reward the correct\n                    -- KI!  If we complete first, it'll adjust the total completed count, and be off by one!\n                    npcUtil.giveKeyItem(player, xi.abyssea.getZoneKIReward(player))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_01.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_01.lua",["SHA256"]="e45504506add9910aae74c7c22bdc6cda93dadb5c8a22ed08067dcbeab7d1aed",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #01\n-----------------------------------\n-- !addquest 8 101\n-- Dominion Sergeant (Zazarg's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_01_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Mechanical_Menace'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 574)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_02.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_02.lua",["SHA256"]="dc9a53eeba22d24d48c1179caf8d8d4ab6a1cd058c9db35f7e2e49001eaeb845",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #02\n-----------------------------------\n-- !addquest 8 102\n-- Dominion Sergeant (Zazarg's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_02_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Spectator'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 575)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_03.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_03.lua",["SHA256"]="bfe4308ae6e6ec8a5028f24a18586c8e43696a20b33306c097d0da51abc8368c",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #03\n-----------------------------------\n-- !addquest 8 103\n-- Dominion Sergeant (Zazarg's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_03_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Sub-zero_Gear'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 576)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_04.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_04.lua",["SHA256"]="e46b2ffb6c1b337ba2b93433217580ab5240abfbd237a1d931e75d7b2657e3fe",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #04\n-----------------------------------\n-- !addquest 8 104\n-- Dominion Sergeant (Maat's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_04_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Snowflake'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 577)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_05.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_05.lua",["SHA256"]="1fa8e6e3f563486272fe0ac20d5e784c96e80541ecf31afdac521428b3d2e330",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #05\n-----------------------------------\n-- !addquest 8 105\n-- Dominion Sergeant (Maat's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_05_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Verglas_Golem'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 578)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_06.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_06.lua",["SHA256"]="9b319b61271014ac40bdc258ec29f7d6dcd9cd111959f25f366458100996161d",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #06\n-----------------------------------\n-- !addquest 8 106\n-- Dominion Sergeant (Maat's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_06_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Olyphant'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 579)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_07.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_07.lua",["SHA256"]="0a676fcc83a6a227e3f487adc6575233f3683e053abd9560ae98edc1a42bebf6",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #07\n-----------------------------------\n-- !addquest 8 107\n-- Dominion Sergeant (Maat's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_07_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Svelldrake'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 580)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Uleguerand_Dominion_Op_08.lua"]={["Path"]="scripts/quests/abyssea/Uleguerand_Dominion_Op_08.lua",["SHA256"]="abea83134ae2920edfd5038686ecbda8d1f1b492192a6ef56dd5ca0a7e4d2dd0",["Text"]="-----------------------------------\n-- Uleguerand - Dominion Op #08\n-----------------------------------\n-- !addquest 8 108\n-- Dominion Sergeant (Maat's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_08_ULEGUERAND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ULEGUERAND] =\n        {\n            ['Adasaurus'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 581)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
